        /// <summary>Xếp các editor vào LayoutControl theo nhóm (chuẩn DevExpress: LayoutControlGroup + LayoutControlItem).</summary>
        private void BuildLayout()
        {
            this.layoutControl1.BeginUpdate();
            try
            {
                System.Drawing.Size labelSize = new System.Drawing.Size(210, 20);

                DevExpress.XtraLayout.LayoutControlGroup grpRoom = AddGroup(this.layoutControlGroupRoot, "Phòng");
                AddItem(grpRoom, "Phòng thu ngân:", this.lblRoomValue, labelSize);
                AddItem(grpRoom, "Tên khoa / khu vực trên tiêu đề:", this.txtDepartmentTitle, labelSize);

                DevExpress.XtraLayout.LayoutControlGroup grpFilter = AddGroup(this.layoutControlGroupRoot, "Điều kiện lọc tivi (không liên quan bộ lọc màn Viện phí)");
                AddItem(grpFilter, "", this.chkAlwaysToday, labelSize).TextVisible = false;
                DevExpress.XtraLayout.LayoutControlItem itemFrom = AddItem(grpFilter, "Ngày vào từ:", this.dtFrom, labelSize);
                DevExpress.XtraLayout.LayoutControlItem itemTo = grpFilter.AddItem("đến:", this.dtTo, itemFrom, DevExpress.XtraLayout.Utils.InsertType.Right);
                itemTo.TextSize = new System.Drawing.Size(40, 20);
                itemTo.Name = "itemDtTo";
                AddItem(grpFilter, "Khoa hiện tại của bệnh nhân:", this.cboDepartments, labelSize);
                AddItem(grpFilter, "Loại điều trị:", this.cboTreatmentTypes, labelSize);
                AddItem(grpFilter, "Đối tượng:", this.cboPatientTypes, labelSize);
                AddItem(grpFilter, "Trạng thái:", this.cboDebtStatus, labelSize);
                AddItem(grpFilter, "Nhóm dịch vụ:", this.cboServiceGroups, labelSize);
                AddItem(grpFilter, "", this.chkSplitCdha, labelSize).TextVisible = false;

                DevExpress.XtraLayout.LayoutControlGroup grpRefresh = AddGroup(this.layoutControlGroupRoot, "Làm mới");
                AddItem(grpRefresh, "Chu kỳ làm mới (giây):", this.spnRefresh, labelSize);
                AddItem(grpRefresh, "Số dòng tối đa trên tivi:", this.spnMaxRows, labelSize);
                AddItem(grpRefresh, "Giây chuyển trang:", this.spnPageSeconds, labelSize);

                DevExpress.XtraLayout.LayoutControlGroup grpDisplay = AddGroup(this.layoutControlGroupRoot, "Hiển thị");
                DevExpress.XtraLayout.LayoutControlItem itemTitleFont = AddItem(grpDisplay, "Cỡ chữ tiêu đề:", this.spnTitleFont, labelSize);
                grpDisplay.AddItem("Màu chữ:", this.clrTitle, itemTitleFont, DevExpress.XtraLayout.Utils.InsertType.Right).TextSize = new System.Drawing.Size(60, 20);
                DevExpress.XtraLayout.LayoutControlItem itemListFont = AddItem(grpDisplay, "Cỡ chữ danh sách:", this.spnListFont, labelSize);
                grpDisplay.AddItem("Màu chữ:", this.clrList, itemListFont, DevExpress.XtraLayout.Utils.InsertType.Right).TextSize = new System.Drawing.Size(60, 20);
                DevExpress.XtraLayout.LayoutControlItem itemCallingFont = AddItem(grpDisplay, "Cỡ chữ đang gọi:", this.spnCallingFont, labelSize);
                grpDisplay.AddItem("Màu tên:", this.clrCalling, itemCallingFont, DevExpress.XtraLayout.Utils.InsertType.Right).TextSize = new System.Drawing.Size(60, 20);
                AddItem(grpDisplay, "Màu nền:", this.clrBack, labelSize);
                AddItem(grpDisplay, "", this.chkExtendMonitor, labelSize).TextVisible = false;
                AddItem(grpDisplay, "", this.chkAutoOpen, labelSize).TextVisible = false;

                System.Drawing.Size rightLabel = new System.Drawing.Size(120, 20);
                DevExpress.XtraLayout.LayoutControlGroup grpListColor = AddGroup(this.layoutControlGroupRoot, "Màu danh sách chờ");
                DevExpress.XtraLayout.LayoutControlItem itemListTitleBack = AddItem(grpListColor, "Nền thanh \"DANH SÁCH CHỜ\":", this.clrListTitleBack, labelSize);
                grpListColor.AddItem("Nền tiêu đề cột:", this.clrColumnHeaderBack, itemListTitleBack, DevExpress.XtraLayout.Utils.InsertType.Right).TextSize = rightLabel;
                AddItem(grpListColor, "Nền dòng xen kẽ:", this.clrRowAltBack, labelSize);

