                DevExpress.XtraLayout.LayoutControlItem itemCallBar = AddItem(grpCallColor, "Nền thanh (bên trái):", this.clrCallBarBack, labelSize);
                grpCallColor.AddItem("Nền (bên phải):", this.clrCallBarBack2, itemCallBar, DevExpress.XtraLayout.Utils.InsertType.Right).TextSize = rightLabel;
