        private static DevExpress.XtraLayout.LayoutControlGroup AddGroup(DevExpress.XtraLayout.LayoutControlGroup parent, string text)
        {
            DevExpress.XtraLayout.LayoutControlGroup group = parent.AddGroup();
            group.Text = text;
            group.Name = "grp_" + text.GetHashCode().ToString("X");
            group.GroupBordersVisible = true;
            group.TextVisible = true;
            return group;
        }

        private static DevExpress.XtraLayout.LayoutControlItem AddItem(DevExpress.XtraLayout.LayoutControlGroup group, string text, System.Windows.Forms.Control control, System.Drawing.Size labelSize)
        {
            DevExpress.XtraLayout.LayoutControlItem item = group.AddItem(text, control);
            item.Name = "item_" + control.Name;
            item.TextSize = labelSize;
            item.TextLocation = DevExpress.Utils.Locations.Left;
            return item;
        }

        private static void InitDateEdit(DevExpress.XtraEditors.DateEdit dt, string name)
        {
            dt.Name = name;
            dt.Properties.Buttons.AddRange(new DevExpress.XtraEditors.Controls.EditorButton[] { new DevExpress.XtraEditors.Controls.EditorButton(DevExpress.XtraEditors.Controls.ButtonPredefines.Combo) });
            dt.Properties.CalendarTimeProperties.Buttons.AddRange(new DevExpress.XtraEditors.Controls.EditorButton[] { new DevExpress.XtraEditors.Controls.EditorButton(DevExpress.XtraEditors.Controls.ButtonPredefines.Combo) });
            dt.Properties.DisplayFormat.FormatString = "dd/MM/yyyy";
            dt.Properties.DisplayFormat.FormatType = DevExpress.Utils.FormatType.DateTime;
            dt.Properties.EditFormat.FormatString = "dd/MM/yyyy";
            dt.Properties.EditFormat.FormatType = DevExpress.Utils.FormatType.DateTime;
            dt.Properties.Mask.EditMask = "dd/MM/yyyy";
            dt.Properties.Mask.UseMaskAsDisplayFormat = true;
        }

        private static void InitCheckedCombo(DevExpress.XtraEditors.CheckedComboBoxEdit cbo, string name)
        {
            cbo.Name = name;
            cbo.Properties.Buttons.AddRange(new DevExpress.XtraEditors.Controls.EditorButton[] { new DevExpress.XtraEditors.Controls.EditorButton(DevExpress.XtraEditors.Controls.ButtonPredefines.Combo) });
            cbo.Properties.SelectAllItemVisible = true;
            cbo.Properties.SeparatorChar = ';';
        }

        private static void InitSpin(DevExpress.XtraEditors.SpinEdit spn, string name, int min, int max, int value)
        {
            spn.Name = name;
            spn.Properties.Buttons.AddRange(new DevExpress.XtraEditors.Controls.EditorButton[] { new DevExpress.XtraEditors.Controls.EditorButton(DevExpress.XtraEditors.Controls.ButtonPredefines.Combo) });
            spn.Properties.IsFloatValue = false;
            spn.Properties.Mask.EditMask = "N00";
            spn.Properties.MinValue = min;
            spn.Properties.MaxValue = max;
            spn.Value = value;
        }

        private static void InitColorPick(DevExpress.XtraEditors.ColorPickEdit clr, string name)
        {
            clr.Name = name;
            clr.Properties.Buttons.AddRange(new DevExpress.XtraEditors.Controls.EditorButton[] { new DevExpress.XtraEditors.Controls.EditorButton(DevExpress.XtraEditors.Controls.ButtonPredefines.Combo) });
            clr.Properties.ShowSystemColors = false;
        }

        #endregion
    }
